x"}}]}]}''',
          )
          as Map;
  final fixtures =
      jsonDecode(
            r'''{"baselineCommit":"bd3d90981271e1f93cf3d1d1a5bbf9b61136b74c","mermaidVersion":"11.17.2","cases":[{"id":"packet-tcp","family":"packet","source":"packet-beta\ntitle TCP\n0-15: \"Source Port\"\n16-31: \"Destination Port\"\n32-63: \"Sequence Number\"\n64-95: \"Acknowledgment Number\""},{"id":"packet-cross-row","family":"packet","source":"packet-beta\n+5: \"Header\"\n+43: \"Cross row\"\n+16: \"Payload\""},{"id":"packet-accessible","family":"packet","source":"packet\naccTitle: Binary frame\naccDescr: Flag and payload fields\n0: \"Flag\"\n1-7: \"Mode\"\n8-31: \"Payload\""},{"id":"packet-configured","family":"packet","source":"%%{init: {\"packet\": {\"bitsPerRow\":16,\"bitWidth\":24,\"showBits\":false}}}%%\npacket-beta\ntitle Configured header\n+9: \"Control\"\n+23: \"Payload\""},{"id":"radar-comparison","family":"radar","source":"radar-beta\naxis focus[\"Focus\"]\naxis clarity[\"Clarity\"]\naxis speed[\"Speed\"]\ncurve Current{focus: 7, clarity: 5, speed: 8}\ncurve Target{focus: 9, clarity: 8, speed: 7}"},{"id":"radar-labels","family":"radar","source":"radar-beta\naxis attack[\"Attack power\"]\naxis defense[\"Defense\"]\naxis speed[\"Speed\"]\ncurve mage[\"Fire mage\"]{attack: 8, defense: 3, speed: 7}\ncurve knight[\"Stone knight\"]{attack: 6, defense: 9, speed: 4}"},{"id":"radar-options","family":"radar","source":"radar-beta\naxis a[\"A\"]\naxis b[\"B\"]\naxis c[\"C\"]\ncurve Low{a: 2, b: 3, c: 4}\nmax 10\nmin 0\nticks 4\nshowLegend false\ngraticule polygon"},{"id":"architecture-services","family":"architecture","source":"architecture-beta\ngroup api(cloud)[API Zone]\nservice web(server)[Web] in api\nservice db(database)[Database] in api\nweb:R --> L:db"},{"id":"architecture-junction","family":"architecture","source":"architecture-beta\nservice client(internet)[Client]\njunction fanout\nservice cache(disk)[Cache]\nclient:R --> L:fanout\nfanout:B --> T:cache"},{"id":"architecture-nested","family":"architecture","source":"architecture-beta\ngroup outer(cloud)[Region]\ngroup inner(server)[Private Network] in outer\nservice app(server)[App] in inner\nservice ext(internet)[External]\napp{group}:R --> L:ext"}]}''',
          )
          as Map;
  final types = <String, Type>{
    'packet': NativeMermaidPacket,
    'radar': NativeMermaidRadar,
    'architecture': NativeMermaidArchitecture,
  };
  for (final input in fixtures['cases'] as List) {
    for (final width in [390.0, 768.0]) {
      for (final brightness in Brightness.values) {
        for (final scale in [1.0, 2.0]) {
          testWidgets('${input['id']} $width ${brightness.name} $scale', (
            tester,
          ) async {
            final semantics = tester.ensureSemantics();
            try {
              final expected = (reference['captures'] as List).firstWhere(
                (c) =>
                    c['id'] == input['id'] &&
                    c['colorScheme'] == brightness.name,
              );
              const boundary = ValueKey('important-diagram');
              await tester.pumpWidget(
                MaterialApp(
                  theme: theme.build(brightness),
                  builder: (context, child) => MediaQuery(
                    data: MediaQuery.of(context).copyWith(
                      textScaler: TextScaler.linear(scale),
                      size: Size(width, 1100),
                      devicePixelRatio: 1,
                    ),
                    child: Align(
                      alignment: Alignment.topLeft,
                      child: SizedBox(
                        width: width,
                        height: 1100,
                        child: child!,
                      ),
                    ),
                  ),
                  home: Scaffold(
                    body: SingleChildScrollView(
                      padding: const EdgeInsets.all(16),
                      child: RepaintBoundary(
                        key: boundary,
                        child: NativeMarkdown(
                          source: '```mermaid\n${input['source']}\n```',
                        ),
                      ),
                    ),
                  ),
                ),
              );
              await tester.pumpAndSettle();
              final figure = find.byWidgetPredicate(
                (widget) => widget.runtimeType == types[input['family']],
              );
              expect(figure, findsOneWidget);
              expect(find.textContaining('Mermaid:'), findsNothing);
              expect(find.text(input['source'] as String), findsNothing);
              final size = tester.getSize(figure);
              expect(size.width, greaterThan(0));
              expect(size.height, greaterThan(0));
              expect(size.width, lessThanOrEqualTo(width - 32));
              final labels = <String>{
                for (final label in expected['labels'] as List)
                  if ((label['text'] as String).isNotEmpty &&
                      !('${label['class']}'.startsWith('packetByte')))
                    label['text'] as String,
              };
              for (final label in labels) {
                expect(
                  find.bySemanticsLabel(RegExp(RegExp.escape(label))),
                  findsWidgets,
                  reason: 'Browser label $label must survive native rendering',
                );
              }
              // Packet/radar have deterministic viewBox scaling; architecture
              // uses a native topology layout with separately checked bounds.
              if (input['family'] != 'architecture' &&
                  [390.0, 768.0].contains(width)) {
                final geometry = (reference['captures'] as List).firstWhere(
                  (c) =>
                      c['id'] == input['id'] &&
                      c['width'] == width &&
                      c['colorScheme'] == brightness.name,
                )['box'];
                final canvas = find.descendant(
                  of: figure,
                  matching: find.byType(CustomPaint),
                );
                expect(canvas, findsOneWidget);
                final paintedSize = tester.getSize(canvas);
                expect(
                  paintedSize.width,
                  closeTo((geometry['width'] as num).toDouble(), 1),
                );
                expect(
                  paintedSize.height,
                  closeTo((geometry['height'] as num).toDouble(), 1),
                );
              }
              // Actual device pixels validate that content is painted,
              // beyond merely finding a mounted renderer or semantic model.
              if (width == 390 && scale == 1) {
                final colors = await tester.runAsync(() async {
                  final image = await tester
                      .renderObject<RenderRepaintBoundary>(find.byKey(boundary))
                      .toImage(pixelRatio: 1);
                  try {
                    final data = (await image.toByteData(
                      format: ui.ImageByteFormat.rawRgba,
                    ))!;
                    final pixels = data.buffer.asUint8List(
                      data.offsetInBytes,
                      data.lengthInBytes,
                    );
                    final unique = <int>{};
                    for (var i = 0; i + 3 < pixels.length; i += 16) {
                      if (pixels[i + 3] > 0) {
                        unique.add(
                          (pixels[i] << 16) |
                              (pixels[i + 1] << 8) |
                              pixels[i + 2],
                        );
                      }
                    }
                    return unique.length;
                  } finally {
                    image.dispose();
                  }
                });
                expect(colors, greaterThan(3));
              }
              expect(tester.takeException(), isNull);
            } finally {
              await tester.pumpWidget(const SizedBox());
              semantics.dispose();
            }
          });
        }
      }
    }
  }
  testWidgets('streaming and invalid source remain recoverable', (
    tester,
  ) async {
    const sources = [
      'packet-beta\n+0: "Invalid"',
      'radar-beta\naxis a["A"]\ncurve x{a: invalid}',
      'architecture-beta\nservice one(server)[One]\none:R -- L:missing',
    ];
    for (final source in sources) {
      for (final ready in [false, true]) {
        await tester.pumpWidget(
          MaterialApp(
            theme: theme.build(Brightness.light),
            home: Scaffold(
              body: NativeMermaid(source: source, ready: ready),
            ),
          ),
        );
        await tester.pump();
        expect(find.text(source), findsOneWidget);
        expect(tester.takeException(), isNull);
      }
    }
  });
}
